  padding: 80px 0;
  background: #f6f2ea;
  min-height: 70vh;
}

.offers-shell, .offer-shell, .external-shell {
  max-width: 1120px;
  margin: 0 auto;
}

.section-head {
  margin-bottom: 28px;
  max-width: 780px;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.78rem;
  color: #b58b4a;
  font-weight: 700;
}

h1, h2, h3 {
  color: #08263a;
}

.card, .offer-card, .external-card {
  background: #fff;
  border-radius: 24px;
  padding: 28px;
  box-shadow: 0 18px 45px rgba(8, 38, 58, 0.08);
  border: 1px solid rgba(8, 38, 58, 0.08);
  margin-bottom: 24px;
}

.form-title {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: center;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
}

label {
  display: grid;
  gap: 6px;
  color: #08263a;
  font-weight: 700;
}

input, textarea, select {
  border: 1px solid rgba(8, 38, 58, 0.16);
  border-radius: 14px;
  padding: 11px 13px;
  font: inherit;
  background: #fff;
}

.wide {
  grid-column: 1/-1;
}

.calculation, .actions, .toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin: 18px 0;
  align-items: end;
}

.calculation span {
  background: #f8f5ef;
  padding: 10px 14px;
  border-radius: 999px;
  color: #516070;
}

.btn {
  border: 0;
  border-radius: 999px;
  padding: 10px 16px;
  font-weight: 700;
  cursor: pointer;
}

.btn-primary {
  background: #08263a;
  color: #fff;
}

.btn-secondary {
  background: #efe7da;
  color: #08263a;
}

.client-link {
  background: #f8f5ef;
  padding: 12px;
  border-radius: 12px;
  word-break: break-all;
  color: #516070;
}

.success {
  color: #047857;
  font-weight: 700;
}

.error, .expired {
  color: #9f1d1d;
  font-weight: 700;
}

.muted {
  color: #667;
}

.search-box {
  flex: 1 1 320px;
}

.offer-list {
  display: grid;
  gap: 12px;
}

.offer-row {
  display: grid;
  grid-template-columns: auto 1.2fr 1.2fr 0.8fr auto;
  gap: 16px;
  align-items: center;
  width: 100%;
  text-align: left;
  background: #fff;
  border: 1px solid rgba(8, 38, 58, 0.08);
  border-radius: 18px;
  padding: 16px;
  cursor: pointer;
  box-shadow: 0 10px 28px rgba(8, 38, 58, 0.06);
}

.offer-row strong, .offer-row small {
  display: block;
}

.offer-row small {
  color: #516070;
}

.status {
  border-radius: 999px;
  padding: 6px 10px;
  background: rgba(181, 139, 74, 0.12);
  color: #8a652d;
  font-weight: 700;
}

.mini-link {
  border: 0;
  background: transparent;
  color: #08263a;
  text-decoration: underline;
  cursor: pointer;
  font-weight: 700;
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 12px;
  margin: 20px 0;
}

.summary-grid div, .step-card, .choice-block {
  background: #f8f5ef;
  border-radius: 18px;
  padding: 16px;
}

.summary-grid strong, .summary-grid span {
  display: block;
}

.summary-grid span {
  color: #516070;
  margin-top: 4px;
}

.terms-check, .radio-card {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  background: #fff;
  border: 1px solid rgba(8, 38, 58, 0.1);
  padding: 14px;
  border-radius: 14px;
  margin: 10px 0;
  color: #516070;
}

@media (max-width: 800px) {
  .offer-row {
    grid-template-columns: 1fr;
  }
}
.external-card h2 {
  margin: 1.5rem 0 0.75rem;
  color: #082b3f;
  font-size: 1.25rem;
}

.full-width {
  display: block;
  margin-top: 1rem;
}

.full-width textarea {
  width: 100%;
  border: 1px solid rgba(8, 43, 63, 0.18);
  border-radius: 12px;
  padding: 0.85rem 1rem;
  font: inherit;
}

.platform-bookings-list {
  margin-top: 1.5rem;
}

.platform-booking-row {
  width: 100%;
  display: grid;
  grid-template-columns: 1.3fr 1.1fr 1fr 0.8fr;
  gap: 1rem;
  align-items: center;
  border: 1px solid rgba(8, 43, 63, 0.1);
  border-radius: 16px;
  background: #fff;
  padding: 1rem;
  margin: 0.75rem 0;
  text-align: left;
  cursor: pointer;
}

.platform-booking-row:hover {
  border-color: rgba(191, 139, 64, 0.45);
  box-shadow: 0 10px 25px rgba(8, 43, 63, 0.08);
}

.platform-booking-row span {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.platform-booking-row small {
  color: #6b7788;
}

@media (max-width: 800px) {
  .platform-booking-row {
    grid-template-columns: 1fr;
  }
}
.external-card select {
  min-height: 44px;
}

.archive-notice {
  margin-top: 1rem;
  padding: 0.9rem 1rem;
  border-radius: 14px;
  background: #eaf7ef;
  color: #155b34;
  border: 1px solid rgba(21, 91, 52, 0.18);
  font-weight: 600;
}

.computed-field {
  background: #f3f7fb;
  border: 1px dashed rgba(8, 43, 63, 0.25);
  border-radius: 14px;
  padding: 0.75rem;
}

.computed-field input[readonly] {
  background: #e9eef5;
  color: #53606f;
  cursor: not-allowed;
}

.computed-field small {
  display: block;
  margin-top: 0.25rem;
  color: #697789;
  font-size: 0.75rem;
}

input:invalid {
  border-color: #c0392b;
}

/* External / historical form polish */
.external-card {
  overflow: hidden;
}

.external-card label {
  min-width: 0;
  overflow-wrap: anywhere;
}

.external-card input,
.external-card select,
.external-card textarea {
  max-width: 100%;
  min-width: 0;
  box-sizing: border-box;
  font-size: 0.95rem;
}

.external-card a {
  margin-top: 0.25rem;
  display: inline-flex;
  color: #0b5e72;
  font-weight: 800;
  text-decoration: none;
  overflow-wrap: anywhere;
}

.boat-url-line {
  background: #fffaf3;
  border-radius: 14px;
  padding: 0.75rem;
  border: 1px solid rgba(191, 139, 64, 0.18);
}

.archive-notice {
  font-size: 0.95rem;
  line-height: 1.45;
}

.computed-field {
  color: #526171;
}

.computed-field input {
  font-size: 0.92rem;
}

.source-direct-note {
  padding: 0.85rem 1rem;
  border-radius: 14px;
  background: #eef9f2;
  color: #155b34;
  font-weight: 700;
