app-terms .updated {
  color: #334155;
  max-width: 920px;
  font-size: 18px;
  line-height: 1.75;
  margin: 0 0 10px;
}

app-terms .updated {
  font-size: 15px;
  font-weight: 700;
  color: #64748b;
}

app-terms .terms-actions {
  display: flex;
  gap: 12px;
  flex-shrink: 0;
  margin-top: 32px;
}

app-terms button {
  border: 0;
  border-radius: 999px;
  padding: 12px 18px;
  font-weight: 800;
  cursor: pointer;
}

app-terms .primary-action {
  background: #ff8a1d;
  color: #fff;
}

app-terms .secondary-action {
  background: #eef6f8;
  color: #08263a;
  border: 1px solid rgba(8, 38, 58, 0.18);
}

app-terms .terms-card {
  width: 100%;
  box-sizing: border-box;
  background: #ffffff;
  border-radius: 30px;
  padding: 64px 76px;
  box-shadow: 0 24px 70px rgba(8, 38, 58, 0.1);
  border: 1px solid rgba(8, 38, 58, 0.12);
}

app-terms .terms-section {
  margin-top: 52px;
  padding-top: 32px;
  border-top: 1px solid rgba(8, 38, 58, 0.1);
}

app-terms .terms-section:first-child {
  margin-top: 0;
  padding-top: 0;
  border-top: 0;
}

app-terms .terms-card h2 {
  color: #08263a;
  margin: 0 0 18px;
  font-size: 30px;
  line-height: 1.25;
  letter-spacing: -0.02em;
}

app-terms .terms-card h3 {
  color: #08263a;
  font-size: 22px;
  line-height: 1.35;
  margin: 0 0 14px;
}

app-terms .terms-card p {
  color: #334155;
  font-size: 18px;
  line-height: 1.85;
  margin: 0 0 18px;
}

app-terms .process-step {
  background: linear-gradient(180deg, #fbfaf7 0%, #f8f5ef 100%);
  border-radius: 22px;
  padding: 30px 34px;
  margin: 20px 0;
  border: 1px solid rgba(8, 38, 58, 0.1);
}

